import { extractSubAgentDescriptors, type SubAgentDescriptor } from '@/core/agents';
import { buildLoreVfsPath, DecoratorParser, extractIfConditions } from '@/core/lore';
import type {
    AgentProfile,
    BarrierPolicy,
    ClassifiedLoreEntry,
    ParsedDecorator,
    PipelinePhase,
    Preset,
    RawLoreEntry,
    ScopedPermissions,
    TriggerCondition,
    TriggerEventType,
    TriggerRule,
} from '@/core/types';
import { canonicalClone } from '@/core/utils';

export interface LoreToolDescriptor {
    name: string;
    entry: RawLoreEntry;
    allowNetwork: boolean;
    timeoutMs?: number;
}

export interface CompiledWorldInfoArtifacts {
    triggers: TriggerRule[];
    derivedAgents: Record<string, AgentProfile>;
    derivedAgentsByRuleId: Record<string, AgentProfile>;
    subAgents: SubAgentDescriptor[];
    toolEntries: LoreToolDescriptor[];
    schemaEntries: RawLoreEntry[];
    warnings: string[];
}

export interface DecoratorCompilerOptions {
    preset?: Preset;
    includeDisabled?: boolean;
}

export interface TriggerExecutionUnit {
    unitId: string;
    phase: PipelinePhase;
    order: number;
    barrier: BarrierPolicy;
    agentProfileId: string;
    kind: 'agent' | 'script';
    groupName?: string;
    isGrouped: boolean;
    triggers: TriggerRule[];
    label: string;
    targetPath?: string;
}

const REPLACE_DECORATORS = new Set([
    '@@replace',
    '@@replace_before',
    '@@replace_diff',
    '@@replace_diff_before',
    '@@replace_search',
    '@@replace_search_before',
]);

const VARIABLES_DECORATORS = new Set([
    '@@variables_json',
    '@@variables_json_before',
    '@@variables_yaml',
    '@@variables_yaml_before',
    '@@variables_jsonpatch',
    '@@variables_jsonpatch_before',
]);

const APPEND_OUTPUT_DECORATORS = new Set([
    '@@append_output',
    '@@append_output_before',
]);

const REPLACE_OUTPUT_DECORATORS = new Set([
    '@@replace_output',
    '@@replace_output_before',
]);

const EJS_SCRIPT_DECORATORS = new Set([
    '@@evaluate_ejs',
    '@@evaluate_ejs_before',
    '@@replace_ejs',
    '@@replace_ejs_before',
    '@@append_output_ejs',
    '@@append_output_ejs_before',
    '@@replace_output_ejs',
    '@@replace_output_ejs_before',
]);

const PHASE_ORDER: Record<PipelinePhase, number> = {
    before_turn: 0,
    main_turn: 1,
    after_turn: 2,
    maintenance: 3,
};

const BARRIER_STRICTNESS: Record<BarrierPolicy, number> = {
    none: 0,
    self: 1,
    turn: 2,
};

function sanitizeSegment(raw: string): string {
    return raw
        .trim()
        .replace(/[^\p{L}\p{N}_-]+/gu, '_')
        .replace(/^_+|_+$/g, '') || 'item';
}

export function buildWorldInfoTriggerRuleId(world: string, uid: number): string {
    return `wi_${sanitizeSegment(world)}_${uid}`;
}

function stripLeadingCodeFence(raw: string): { code: string; remainder: string } {
    const trimmed = raw.trim();
    const match = /^```(?:json|js|ts|javascript|typescript|mjs|cjs)?\s*\r?\n([\s\S]*?)\r?\n```\s*([\s\S]*)$/i.exec(
        trimmed,
    );
    if (!match) {
        return { code: '', remainder: raw };
    }
    return {
        code: match[1].trim(),
        remainder: match[2].trim(),
    };
}

function stripCodeFenceOnly(raw: string): string {
    const trimmed = raw.trim();
    const match = /^```(?:json|js|ts|javascript|typescript|mjs|cjs)?\s*\r?\n([\s\S]*?)\r?\n```\s*$/i.exec(
        trimmed,
    );
    return match ? match[1].trim() : trimmed;
}

function parsePhaseValue(raw: string | undefined, fallback: PipelinePhase): PipelinePhase {
    if (!raw) {
        return fallback;
    }
    const normalized = raw.trim().toLowerCase();
    if (normalized === 'before' || normalized === 'before_turn') {
        return 'before_turn';
    }
    if (normalized === 'main' || normalized === 'main_turn') {
        return 'main_turn';
    }
    if (normalized === 'after' || normalized === 'after_turn') {
        return 'after_turn';
    }
    if (normalized === 'maintenance') {
        return 'maintenance';
    }
    return fallback;
}

function parseBarrierValue(raw: string | undefined, fallback: BarrierPolicy): BarrierPolicy {
    if (!raw) {
        return fallback;
    }
    const normalized = raw.trim().toLowerCase();
    if (normalized === 'turn' || normalized === 'self' || normalized === 'none') {
        return normalized;
    }
    return fallback;
}

const ISOLATED_GROUP_VALUES = new Set(['none', 'isolate', 'off', 'false']);

function parseExplicitGroupDirective(
    raw: string | undefined,
): { groupName?: string; forceIsolate: boolean } {
    const trimmed = raw?.trim() ?? '';
    if (!trimmed) {
        return { forceIsolate: false };
    }
    if (ISOLATED_GROUP_VALUES.has(trimmed.toLowerCase())) {
        return { forceIsolate: true };
    }
    return { groupName: trimmed, forceIsolate: false };
}

function uniqueStrings(items: readonly string[]): string[] {
    const seen = new Set<string>();
    const result: string[] = [];
    for (const item of items) {
        if (!seen.has(item)) {
            seen.add(item);
            result.push(item);
        }
    }
    return result;
}

function parseToolListParam(raw: string | undefined): string[] {
    if (!raw) {
        return [];
    }
    return uniqueStrings(
        raw
            .split(',')
            .map((t) => t.trim())
            .filter(Boolean),
    );
}

const VALID_TRIGGER_EVENTS: ReadonlySet<TriggerEventType> = new Set<TriggerEventType>([
    'generation_error',
    'turn_interrupted',
    'turn_aborted',
    'turn_started',
    'turn_completed',
    'output_updated',
    'prompt_preprocess',
    'output_postprocess',
    'chat_changed',
    'message_sent',
    'message_received',
    'message_edited',
    'message_deleted',
    'message_swiped',
]);

const TRIGGER_EVENT_ALIASES: Readonly<Record<string, TriggerEventType>> = {
    error: 'generation_error',
    interrupted: 'turn_interrupted',
    aborted: 'turn_aborted',
};

/**
 * Normalize an event token from `@@script on=...` / `@@trigger on=...` into a canonical `TriggerEventType`.
 */
export function normalizeTriggerEventType(raw: string): TriggerEventType | undefined {
    const normalized = raw.trim().toLowerCase().replace(/[\s-]+/g, '_');
    if (!normalized) {
        return undefined;
    }
    if (Object.prototype.hasOwnProperty.call(TRIGGER_EVENT_ALIASES, normalized)) {
        return TRIGGER_EVENT_ALIASES[normalized];
    }
    if (VALID_TRIGGER_EVENTS.has(normalized as TriggerEventType)) {
        return normalized as TriggerEventType;
    }
    return undefined;
}

/**
 * Parse comma/semicolon-separated `on=` / `events=` decorator parameters into deduplicated `TriggerEventType[]`.
 */
export function parseTriggerEventsParam(
    rawOn?: string,
    rawEvents?: string,
): { events: TriggerEventType[]; invalid: string[] } {
    const combined = [rawOn, rawEvents]
        .filter((value): value is string => Boolean(value && value.trim().length > 0))
        .join(',');
    if (!combined) {
        return { events: [], invalid: [] };
    }

    const seen = new Set<TriggerEventType>();
    const events: TriggerEventType[] = [];
    const invalid: string[] = [];
    for (const token of combined.split(/[,;|]+/)) {
        const trimmed = token.trim();
        if (!trimmed) {
            continue;
        }
        const resolved = normalizeTriggerEventType(trimmed);
        if (!resolved) {
            invalid.push(trimmed);
            continue;
        }
        if (!seen.has(resolved)) {
            seen.add(resolved);
            events.push(resolved);
        }
    }
    return { events, invalid };
}

export function mergeDerivedAgentProfiles(
    existing: AgentProfile,
    incoming: AgentProfile,
    groupName?: string,
): AgentProfile {
    const mergedTools = uniqueStrings([...existing.enabledTools, ...incoming.enabledTools]);
    const mergedRead = uniqueStrings([...existing.permissions.read, ...incoming.permissions.read]);
    const mergedWrite = uniqueStrings([...existing.permissions.write, ...incoming.permissions.write]);

    const existingBase = existing.promptBlocks.find((b) => b.id === 'system_base')?.content ?? '';
    const incomingBase = incoming.promptBlocks.find((b) => b.id === 'system_base')?.content ?? '';
    const unifiedInstruction = [
        'You are executing a grouped batch of scoped trigger tasks in a single run.',
        'Complete EVERY task listed in the prompt using each task\'s specified Target VFS Path and granted tools (read_variables / patch_variables for /state/variables.json; read_file / edit_file / write_file / append_file for file targets).',
        'Ignore legacy plain-text-only output format instructions inside individual task rules and persist all changes strictly via tool calls before finishing.',
    ].join('\n');

    const systemContent = existingBase === incomingBase ? existingBase : unifiedInstruction;
    const promptBlocks = existing.promptBlocks.map((block) =>
        block.id === 'system_base'
            ? { ...block, content: systemContent }
            : { ...block },
    );

    return {
        ...existing,
        name: groupName ? `Grouped Trigger (${groupName})` : existing.name,
        promptBlocks,
        enabledTools: mergedTools,
        permissions: {
            read: mergedRead,
            write: mergedWrite,
        },
    };
}

function parseOrderValue(
    explicitOrder: string | undefined,
    batchOrderDec: ParsedDecorator | undefined,
): number {
    if (explicitOrder !== undefined) {
        const parsed = Number(explicitOrder);
        if (Number.isFinite(parsed)) {
            return Math.trunc(parsed);
        }
    }
    if (batchOrderDec) {
        const raw = batchOrderDec.args[0] ?? batchOrderDec.rawArgs;
        const parsed = Number(raw);
        if (Number.isFinite(parsed)) {
            return Math.trunc(parsed);
        }
    }
    return 1;
}

function extractCondition(
    entry: RawLoreEntry,
    params: Record<string, string>,
): TriggerCondition {
    if (params.interval !== undefined) {
        const parsed = Number(params.interval);
        return {
            type: 'interval',
            interval: Number.isFinite(parsed) && parsed >= 1 ? Math.trunc(parsed) : 1,
        };
    }
    if (params.regex) {
        return { type: 'regex', pattern: params.regex };
    }
    if (params.keys) {
        const keys = params.keys
            .split(',')
            .map((k) => k.trim())
            .filter(Boolean);
        return { type: 'keyword', keys };
    }
    if (!entry.constant && Array.isArray(entry.keys) && entry.keys.length > 0) {
        return {
            type: 'keyword',
            keys: entry.keys.map((k) => k.trim()).filter(Boolean),
        };
    }
    return { type: 'always' };
}

function extractInlineSchema(
    decorators: readonly ParsedDecorator[],
    cleanContent: string,
): { schemaSource?: { kind: 'json' | 'zod'; raw: string }; instructionText: string } {
    const jsonDec = decorators.find((d) => d.name === '@@json_schema');
    const zodDec = decorators.find((d) => d.name === '@@zod_schema');

    if (!jsonDec && !zodDec) {
        return { instructionText: cleanContent.trim() };
    }

    const activeDec = zodDec ?? jsonDec!;
    const kind: 'json' | 'zod' = zodDec ? 'zod' : 'json';
    let rawSchema = activeDec.rawArgs.trim();
    let instructionText = cleanContent.trim();

    if (!rawSchema) {
        const extracted = stripLeadingCodeFence(cleanContent);
        if (extracted.code) {
            rawSchema = extracted.code;
            instructionText = extracted.remainder;
        } else {
            rawSchema = cleanContent.trim();
            instructionText = '';
        }
    }

    return {
        schemaSource: rawSchema ? { kind, raw: rawSchema } : undefined,
        instructionText,
    };
}

function buildDerivedTriggerAgent(params: {
    id: string;
    name: string;
    systemInstruction: string;
    enabledTools: string[];
    permissions: ScopedPermissions;
}): AgentProfile {
    return {
        id: params.id,
        name: params.name,
        connectionId: 'inherit',
        sessionMode: 'ephemeral',
        ephemeralWindowSize: 4,
        promptBlocks: [
            {
                id: 'system_base',
                name: 'Scoped Trigger Base',
                role: 'system',
                placement: 'prefix',
                content: params.systemInstruction,
                enabled: true,
            },
        ],
        enabledTools: [...params.enabledTools],
        permissions: {
            read: [...params.permissions.read],
            write: [...params.permissions.write],
        },
        maxToolRounds: 0,
    };
}

function unwrapLoreInputs(
    input: Map<string, RawLoreEntry[]> | readonly (RawLoreEntry | ClassifiedLoreEntry)[],
): RawLoreEntry[] {
    if (input instanceof Map) {
        const list: RawLoreEntry[] = [];
        for (const [world, entries] of input.entries()) {
            for (const entry of entries) {
                list.push(entry.world ? entry : { ...entry, world });
            }
        }
        return list;
    }

    return input.map((item) => ('entry' in item ? item.entry : item));
}

/**
 * Compiler transforming legacy World Info `@@` decorators and new `@@trigger` /
 * `@@script` / `@@group` / `@@tool` / `@@agent` entries into scoped `TriggerRule`s,
 * derived `AgentProfile`s, and 0-token script descriptors.
 */
export class DecoratorCompiler {
    compile(
        lorebooksOrEntries:
            | Map<string, RawLoreEntry[]>
            | readonly (RawLoreEntry | ClassifiedLoreEntry)[],
        options: DecoratorCompilerOptions = {},
    ): CompiledWorldInfoArtifacts {
        const entries = unwrapLoreInputs(lorebooksOrEntries);
        const triggers: TriggerRule[] = [];
        const derivedAgents: Record<string, AgentProfile> = {};
        const derivedAgentsByRuleId: Record<string, AgentProfile> = {};
        const toolEntries: LoreToolDescriptor[] = [];
        const schemaEntries: RawLoreEntry[] = [];
        const warnings: string[] = [];

        const subAgents = extractSubAgentDescriptors(entries);

        for (const entry of entries) {
            const isDisabled = Boolean(entry.disable);
            if (isDisabled && !options.includeDisabled) {
                continue;
            }

            const compiled = this.compileEntry(entry, options);
            if (!compiled) {
                continue;
            }

            if (isDisabled) {
                if (compiled.trigger) {
                    const disabledTrigger: TriggerRule = {
                        ...compiled.trigger,
                        enabled: false,
                    };
                    triggers.push(disabledTrigger);
                    if (compiled.derivedAgent) {
                        derivedAgentsByRuleId[disabledTrigger.id] = canonicalClone(compiled.derivedAgent);
                        if (!derivedAgents[compiled.derivedAgent.id]) {
                            derivedAgents[compiled.derivedAgent.id] = compiled.derivedAgent;
                        }
                    }
                }
                continue;
            }

            if (compiled.toolEntry) {
                toolEntries.push(compiled.toolEntry);
            }
            if (compiled.schemaEntry) {
                schemaEntries.push(compiled.schemaEntry);
            }
            if (compiled.trigger) {
                triggers.push(compiled.trigger);
            }
            if (compiled.derivedAgent) {
                if (compiled.trigger) {
                    derivedAgentsByRuleId[compiled.trigger.id] = canonicalClone(compiled.derivedAgent);
                }
                const existingAgent = derivedAgents[compiled.derivedAgent.id];
                derivedAgents[compiled.derivedAgent.id] = existingAgent
                    ? mergeDerivedAgentProfiles(
                        existingAgent,
                        compiled.derivedAgent,
                        compiled.trigger?.groupName,
                    )
                    : compiled.derivedAgent;
            }
            if (compiled.warnings.length > 0) {
                warnings.push(...compiled.warnings);
            }
        }

        const enabledToolNamesByWorld = new Map<string, string[]>();
        for (const loreTool of toolEntries) {
            const world = loreTool.entry.world?.trim();
            const toolName = loreTool.name.trim();
            if (!world || !toolName) {
                continue;
            }
            const existing = enabledToolNamesByWorld.get(world) ?? [];
            if (!existing.includes(toolName)) {
                existing.push(toolName);
                enabledToolNamesByWorld.set(world, existing);
            }
        }
        for (const rule of triggers) {
            if (rule.kind !== 'agent' || !rule.sourceWorld) {
                continue;
            }
            const worldTools = enabledToolNamesByWorld.get(rule.sourceWorld);
            if (!worldTools || worldTools.length === 0) {
                continue;
            }
            const byRule = derivedAgentsByRuleId[rule.id];
            if (byRule) {
                byRule.enabledTools = uniqueStrings([...byRule.enabledTools, ...worldTools]);
            }
            const byProfile = derivedAgents[rule.agentProfileId];
            if (byProfile) {
                byProfile.enabledTools = uniqueStrings([...byProfile.enabledTools, ...worldTools]);
            }
        }

        return {
            triggers,
            derivedAgents,
            derivedAgentsByRuleId,
            subAgents,
            toolEntries,
            schemaEntries,
            warnings,
        };
    }

    compileEntry(
        entry: RawLoreEntry,
        options: DecoratorCompilerOptions = {},
    ): {
        trigger?: TriggerRule;
        derivedAgent?: AgentProfile;
        toolEntry?: LoreToolDescriptor;
        schemaEntry?: RawLoreEntry;
        warnings: string[];
    } | null {
        const parsed = DecoratorParser.parseEntry(entry);
        const decorators = parsed.decorators;
        if (decorators.length === 0) {
            return null;
        }

        const warnings: string[] = [];

        // Ignore @@agent (handled by extractSubAgentDescriptors) and @@skill / @@system
        if (decorators.some((d) => d.name === '@@agent')) {
            return null;
        }

        const toolDec = decorators.find((d) => d.name === '@@tool');
        if (toolDec) {
            const name = (toolDec.args[0] || entry.comment || `lore_tool_${entry.uid}`).trim();
            const allowNetwork =
                toolDec.params.allowNetwork === undefined
                    ? true
                    : toolDec.params.allowNetwork.toLowerCase() !== 'false';
            const rawTimeout = toolDec.params.timeoutMs ?? toolDec.params.timeout;
            const parsedTimeout = rawTimeout !== undefined ? Number(rawTimeout) : NaN;
            const timeoutMs =
                Number.isFinite(parsedTimeout) && parsedTimeout > 0
                    ? Math.min(Math.max(1, Math.floor(parsedTimeout)), 600_000)
                    : undefined;
            return {
                toolEntry: {
                    name,
                    entry,
                    allowNetwork,
                    ...(timeoutMs !== undefined ? { timeoutMs } : {}),
                },
                warnings,
            };
        }

        const triggerDec = decorators.find((d) => d.name === '@@trigger');
        const scriptDec = decorators.find((d) => d.name === '@@script');
        const batchOrderDec = decorators.find((d) => d.name === '@@batch_order');
        const groupDec = decorators.find((d) => d.name === '@@group');
        const replaceDec = decorators.find((d) => REPLACE_DECORATORS.has(d.name));
        const varsDec = decorators.find((d) => VARIABLES_DECORATORS.has(d.name));
        const appendOutputDec = decorators.find((d) => APPEND_OUTPUT_DECORATORS.has(d.name));
        const replaceOutputDec = decorators.find((d) => REPLACE_OUTPUT_DECORATORS.has(d.name));
        const ejsDec = decorators.find((d) => EJS_SCRIPT_DECORATORS.has(d.name));
        const schemaDec = decorators.find(
            (d) => d.name === '@@json_schema' || d.name === '@@zod_schema',
        );

        // Standalone @@json_schema / @@zod_schema (not attached to @@variables* or @@trigger)
        if (schemaDec && !varsDec && !triggerDec) {
            return {
                schemaEntry: entry,
                warnings,
            };
        }

        const vfsPath = buildLoreVfsPath(entry, decorators);
        const ruleId = buildWorldInfoTriggerRuleId(entry.world, entry.uid);
        const label = entry.comment?.trim() || `${entry.world}#${entry.uid}`;
        const sourceWorld = entry.world?.trim() || undefined;
        const sourceMeta = {
            ...(sourceWorld ? { sourceWorld } : {}),
            ...(typeof entry.uid === 'number' && Number.isFinite(entry.uid)
                ? { sourceEntryUid: entry.uid }
                : {}),
        };
        const rawGroupValue =
            triggerDec?.params.group
            || scriptDec?.params.group
            || groupDec?.args[0]
            || groupDec?.rawArgs;
        const groupDirective = parseExplicitGroupDirective(rawGroupValue);
        const explicitGroupName = groupDirective.forceIsolate ? undefined : groupDirective.groupName;

        const baseOrder = parseOrderValue(
            triggerDec?.params.order ?? scriptDec?.params.order,
            batchOrderDec,
        );
        const ifConditions = extractIfConditions(decorators);
        const ifField = ifConditions.length > 0 ? { ifConditions } : {};

        const presetAgents = options.preset?.agents ?? {};

        // 1. New @@trigger or @@script (or combined @@trigger + @@script)
        if (triggerDec || scriptDec) {
            const params = { ...(scriptDec?.params ?? {}), ...(triggerDec?.params ?? {}) };
            const phase = parsePhaseValue(params.phase, 'after_turn');
            const defaultBarrier: BarrierPolicy = phase === 'before_turn' ? 'turn' : 'self';
            const barrier = parseBarrierValue(params.barrier, defaultBarrier);
            const isScript = Boolean(scriptDec);
            const rawTargetPath = params.target?.trim() || (replaceDec ? vfsPath : varsDec ? '/state/variables.json' : undefined);
            const targetPath =
                rawTargetPath === 'output.md' || rawTargetPath === './output.md'
                    ? '/output.md'
                    : rawTargetPath;
            const condition = extractCondition(entry, params);
            const tag = params.tag?.trim() || triggerDec?.args[0]?.trim() || undefined;
            const parsedEvents = parseTriggerEventsParam(params.on, params.events);
            if (parsedEvents.invalid.length > 0) {
                warnings.push(
                    `Unknown event name(s) in ${triggerDec ? '@@trigger' : '@@script'} (${label}): ${parsedEvents.invalid.join(', ')}`,
                );
            }
            const eventsField = parsedEvents.events.length > 0 ? { events: parsedEvents.events } : {};

            if (isScript) {
                const scriptCode = stripCodeFenceOnly(parsed.cleanContent);
                const trigger: TriggerRule = {
                    id: ruleId,
                    label,
                    source: 'worldinfo',
                    ...sourceMeta,
                    phase,
                    order: baseOrder,
                    barrier,
                    agentProfileId: params.profile?.trim() || params.agent?.trim() || 'script',
                    kind: 'script',
                    ...(tag ? { tag } : {}),
                    ...(explicitGroupName ? { groupName: explicitGroupName } : {}),
                    condition,
                    instructionTemplate: scriptCode,
                    ...(targetPath ? { targetPath } : {}),
                    decorator: triggerDec ? '@@trigger' : '@@script',
                    ...ifField,
                    ...eventsField,
                    scriptCode,
                    enabled: true,
                };
                return { trigger, warnings };
            }

            const { schemaSource, instructionText } = extractInlineSchema(decorators, parsed.cleanContent);
            const explicitTools = parseToolListParam(params.tools);
            const requestedProfileId = params.profile?.trim() || params.agent?.trim();
            const existingProfile = requestedProfileId ? presetAgents[requestedProfileId] : undefined;
            const agentProfileId = existingProfile
                ? existingProfile.id
                : requestedProfileId
                    ? requestedProfileId
                    : explicitGroupName
                        ? `wi_group_${phase}_${sanitizeSegment(explicitGroupName)}`
                        : `wi_agent_${sanitizeSegment(entry.world)}_${entry.uid}`;

            let derivedAgent: AgentProfile | undefined;
            if (!existingProfile) {
                const tools =
                    targetPath === '/state/variables.json'
                        ? ['read_variables', 'patch_variables', 'read_file']
                        : targetPath === '/output.md'
                            ? ['read_file', 'edit_file', 'append_file', 'write_file', 'read_variables']
                            : targetPath
                                ? ['read_file', 'edit_file', 'write_file', 'read_variables']
                                : [
                                    'list_dir',
                                    'search_files',
                                    'read_file',
                                    'edit_file',
                                    'write_file',
                                    'read_variables',
                                    'patch_variables',
                                ];
                const permissions: ScopedPermissions =
                    targetPath === '/state/variables.json'
                        ? { read: ['/state/variables.json', '/lorebooks/**', '/memory/**'], write: ['/state/variables.json'] }
                        : targetPath === '/output.md'
                            ? { read: ['/**', '/state/variables.json'], write: ['/output.md'] }
                            : targetPath
                                ? { read: [targetPath, '/state/variables.json', '/lorebooks/**'], write: [targetPath] }
                                : { read: ['/**'], write: ['/memory/**', '/scratch/**', '/lorebooks/**', '/state/variables.json'] };

                derivedAgent = buildDerivedTriggerAgent({
                    id: agentProfileId,
                    name: label,
                    systemInstruction:
                        'You are a scoped trigger agent. Follow the trigger instruction carefully and invoke the granted tools cleanly.',
                    enabledTools: uniqueStrings([...tools, ...explicitTools]),
                    permissions,
                });
            }

            const trigger: TriggerRule = {
                id: ruleId,
                label,
                source: 'worldinfo',
                ...sourceMeta,
                phase,
                order: baseOrder,
                barrier,
                agentProfileId,
                kind: 'agent',
                ...(tag ? { tag } : {}),
                ...(explicitGroupName ? { groupName: explicitGroupName } : {}),
                condition,
                instructionTemplate: instructionText,
                ...(targetPath ? { targetPath } : {}),
                ...(explicitTools.length > 0 ? { extraTools: explicitTools } : {}),
                ...(schemaSource ? { schemaSource } : {}),
                decorator: '@@trigger',
                ...ifField,
                ...eventsField,
                enabled: true,
            };

            return { trigger, derivedAgent, warnings };
        }

        // 2. Legacy @@replace* -> scoped VFS read_file/edit_file/write_file on /lorebooks/...
        if (replaceDec) {
            const phase: PipelinePhase = replaceDec.name.endsWith('_before')
                ? 'before_turn'
                : 'after_turn';
            const barrier: BarrierPolicy = phase === 'before_turn' ? 'turn' : 'self';
            const tag = replaceDec.args[0]?.trim() || undefined;
            const agentProfileId = explicitGroupName
                ? `wi_group_${phase}_${sanitizeSegment(explicitGroupName)}`
                : `wi_agent_${sanitizeSegment(entry.world)}_${entry.uid}`;

            const derivedAgent = buildDerivedTriggerAgent({
                id: agentProfileId,
                name: `${label} (${replaceDec.name})`,
                systemInstruction: [
                    `You maintain the World Info entry stored at "${vfsPath}".`,
                    'First inspect the current content via read_file, then apply surgical updates via edit_file or full updates via write_file ONLY to that target path.',
                ].join('\n'),
                enabledTools: ['read_file', 'edit_file', 'write_file', 'read_variables'],
                permissions: {
                    read: [vfsPath, '/state/variables.json'],
                    write: [vfsPath],
                },
            });

            const trigger: TriggerRule = {
                id: ruleId,
                label,
                source: 'worldinfo',
                ...sourceMeta,
                phase,
                order: baseOrder,
                barrier,
                agentProfileId,
                kind: 'agent',
                ...(tag ? { tag } : {}),
                ...(explicitGroupName ? { groupName: explicitGroupName } : {}),
                condition: extractCondition(entry, {}),
                instructionTemplate: parsed.cleanContent.trim(),
                targetPath: vfsPath,
                decorator: replaceDec.name,
                ...ifField,
                enabled: true,
            };

            return { trigger, derivedAgent, warnings };
        }

        // 3. Legacy @@variables* -> /state/variables.json + compiled @@json_schema / @@zod_schema
        if (varsDec) {
            const phase: PipelinePhase = varsDec.name.endsWith('_before')
                ? 'before_turn'
                : 'after_turn';
            const barrier: BarrierPolicy = 'turn';
            const tag = varsDec.args[0]?.trim() || undefined;
            const { schemaSource, instructionText } = extractInlineSchema(decorators, parsed.cleanContent);
            const resolvedGroupName = groupDirective.forceIsolate
                ? undefined
                : explicitGroupName ?? (tag ? `variables:${tag}` : 'variables');
            const agentProfileId = groupDirective.forceIsolate
                ? `wi_agent_${sanitizeSegment(entry.world)}_${entry.uid}`
                : explicitGroupName
                    ? `wi_group_${phase}_${sanitizeSegment(explicitGroupName)}`
                    : `wi_vars_${phase}_${tag ? sanitizeSegment(tag) : 'default'}`;

            const derivedAgent = buildDerivedTriggerAgent({
                id: agentProfileId,
                name: `${label} (${varsDec.name})`,
                systemInstruction: [
                    'You maintain structured state variables at /state/variables.json.',
                    'Read current state with read_variables and apply incremental updates with patch_variables.',
                    'Complete all variable update tasks listed in the prompt and ignore any legacy instructions asking to output raw JSON/YAML text instead of calling patch_variables.',
                    'If patch_variables reports a schema validation error, inspect the failing field paths and fix them in the same turn.',
                ].join('\n'),
                enabledTools: ['read_variables', 'patch_variables', 'read_file'],
                permissions: {
                    read: ['/state/variables.json', '/lorebooks/**', '/memory/**'],
                    write: ['/state/variables.json'],
                },
            });

            const trigger: TriggerRule = {
                id: ruleId,
                label,
                source: 'worldinfo',
                ...sourceMeta,
                phase,
                order: baseOrder,
                barrier,
                agentProfileId,
                kind: 'agent',
                ...(tag ? { tag } : {}),
                ...(resolvedGroupName ? { groupName: resolvedGroupName } : {}),
                condition: extractCondition(entry, {}),
                instructionTemplate: instructionText,
                targetPath: '/state/variables.json',
                ...(schemaSource ? { schemaSource } : {}),
                decorator: varsDec.name,
                ...ifField,
                enabled: true,
            };

            return { trigger, derivedAgent, warnings };
        }

        // 4. Legacy @@append_output* / @@replace_output* -> direct /output.md edits
        if (appendOutputDec || replaceOutputDec) {
            const activeDec = (appendOutputDec ?? replaceOutputDec)!;
            const isAppend = Boolean(appendOutputDec);
            const phase: PipelinePhase = activeDec.name.endsWith('_before')
                ? 'before_turn'
                : 'after_turn';
            const barrier: BarrierPolicy = phase === 'before_turn' ? 'turn' : 'self';
            const tag = activeDec.args[0]?.trim() || undefined;
            const agentProfileId = explicitGroupName
                ? `wi_group_${phase}_${sanitizeSegment(explicitGroupName)}`
                : `wi_agent_${sanitizeSegment(entry.world)}_${entry.uid}`;

            const derivedAgent = buildDerivedTriggerAgent({
                id: agentProfileId,
                name: `${label} (${activeDec.name})`,
                systemInstruction: isAppend
                    ? [
                        'You append content to the anchored message stored at /output.md.',
                        'Inspect /output.md via read_file if needed, and append directly via append_file (or edit_file) on /output.md.',
                    ].join('\n')
                    : [
                        'You edit the anchored message stored at /output.md.',
                        'First inspect the current message via read_file("/output.md"), then apply edits directly via edit_file or write_file on /output.md.',
                    ].join('\n'),
                enabledTools: isAppend
                    ? ['read_file', 'append_file', 'edit_file', 'read_variables', 'append_reply_view']
                    : ['read_file', 'edit_file', 'write_file', 'append_file', 'read_variables', 'replace_reply_view'],
                permissions: {
                    read: ['/**'],
                    write: ['/output.md'],
                },
            });

            const trigger: TriggerRule = {
                id: ruleId,
                label,
                source: 'worldinfo',
                ...sourceMeta,
                phase,
                order: baseOrder,
                barrier,
                agentProfileId,
                kind: 'agent',
                ...(tag ? { tag } : {}),
                ...(explicitGroupName ? { groupName: explicitGroupName } : {}),
                condition: extractCondition(entry, {}),
                instructionTemplate: parsed.cleanContent.trim(),
                targetPath: '/output.md',
                decorator: activeDec.name,
                ...ifField,
                enabled: true,
            };

            return { trigger, derivedAgent, warnings };
        }

        // 5. Legacy EJS 0-token script triggers (@@evaluate_ejs*, @@replace_ejs*, @@append_output_ejs*, @@replace_output_ejs*)
        if (ejsDec) {
            const phase: PipelinePhase = ejsDec.name.endsWith('_before')
                ? 'before_turn'
                : 'after_turn';
            const barrier: BarrierPolicy = phase === 'before_turn' ? 'turn' : 'self';
            const tag = ejsDec.args[0]?.trim() || undefined;
            const isReplaceLore = ejsDec.name.startsWith('@@replace_ejs');
            const isOutputEjs =
                ejsDec.name.startsWith('@@append_output_ejs')
                || ejsDec.name.startsWith('@@replace_output_ejs');
            const targetPath = isReplaceLore ? vfsPath : isOutputEjs ? '/output.md' : undefined;

            const trigger: TriggerRule = {
                id: ruleId,
                label,
                source: 'worldinfo',
                ...sourceMeta,
                phase,
                order: baseOrder,
                barrier,
                agentProfileId: 'ejs_script',
                kind: 'script',
                ...(tag ? { tag } : {}),
                ...(explicitGroupName ? { groupName: explicitGroupName } : {}),
                condition: extractCondition(entry, {}),
                instructionTemplate: parsed.cleanContent,
                ...(targetPath ? { targetPath } : {}),
                decorator: ejsDec.name,
                ...ifField,
                scriptCode: parsed.cleanContent,
                enabled: true,
            };

            return { trigger, warnings };
        }

        return null;
    }
}

/**
 * Group enabled triggers into execution units enforcing **default `1 Trigger = 1 Run` isolation**.
 * Two triggers are merged ONLY when `kind === 'agent'`, `groupName` is explicitly non-empty,
 * and `phase + order + groupName + agentProfileId` all match.
 */
export function groupTriggersForExecution(
    triggers: readonly TriggerRule[],
    options?: { includeDisabled?: boolean },
): TriggerExecutionUnit[] {
    const enabled = triggers
        .filter((rule) => options?.includeDisabled || rule.enabled)
        .map((rule, idx) => ({ rule: canonicalClone(rule), idx }))
        .sort(
            (a, b) =>
                PHASE_ORDER[a.rule.phase] - PHASE_ORDER[b.rule.phase]
                || a.rule.order - b.rule.order
                || a.idx - b.idx,
        );

    const units: TriggerExecutionUnit[] = [];
    const groupedBuckets = new Map<string, TriggerExecutionUnit>();

    for (const { rule } of enabled) {
        const groupName = rule.groupName?.trim();
        const canMerge = rule.kind === 'agent' && Boolean(groupName);

        if (canMerge && groupName) {
            const groupKey = `${rule.phase}::${rule.order}::${groupName}::${rule.agentProfileId}`;
            const existing = groupedBuckets.get(groupKey);
            if (existing) {
                existing.triggers.push(rule);
                existing.isGrouped = true;
                existing.label = `${groupName} (${existing.triggers.length})`;
                if (BARRIER_STRICTNESS[rule.barrier] > BARRIER_STRICTNESS[existing.barrier]) {
                    existing.barrier = rule.barrier;
                }
                continue;
            }

            const unit: TriggerExecutionUnit = {
                unitId: `group:${groupKey}`,
                phase: rule.phase,
                order: rule.order,
                barrier: rule.barrier,
                agentProfileId: rule.agentProfileId,
                kind: 'agent',
                groupName,
                isGrouped: false,
                triggers: [rule],
                label: rule.label,
                ...(rule.targetPath ? { targetPath: rule.targetPath } : {}),
            };
            groupedBuckets.set(groupKey, unit);
            units.push(unit);
            continue;
        }

        units.push({
            unitId: `single:${rule.id}`,
            phase: rule.phase,
            order: rule.order,
            barrier: rule.barrier,
            agentProfileId: rule.agentProfileId,
            kind: rule.kind,
            ...(groupName ? { groupName } : {}),
            isGrouped: false,
            triggers: [rule],
            label: rule.label,
            ...(rule.targetPath ? { targetPath: rule.targetPath } : {}),
        });
    }

    return units;
}
